// Reference: backend/src/Smartlog.Application/Features/Security/Roles/Queries/GetRoleById.cs
public record Query(Guid Id) : IQuery<RoleDto?>;

public class QueryHandler(IAppDbContext context) : IQueryHandler<Query, RoleDto?> {
    public async Task<RoleDto?> HandleAsync(Query query, CancellationToken ct = default) {
        var entity = await context.UserRoles
            .AsNoTracking()
            .FirstOrDefaultAsync(r => r.Id == query.Id, ct);
        return entity?.ToRoleDto();
    }
}

// DynamicGrid query pattern:
public record Query : DynamicListQuery, IDynamicGridQuery, IQuery<DynamicGridResult> {
    public string FormCode { get; init; } = "SYSROLEG01";
    public string? SearchFormCode { get; init; } = "SYSROLES01";
    public Dictionary<string, object?>? FilterValues { get; init; }
}

public class QueryHandler(IServiceProvider serviceProvider, ICurrentUser currentUser)
    : DynamicGridQueryHandler<Query>(serviceProvider), IQueryHandler<Query, DynamicGridResult> {
    protected override string GetConfigName() => "Roles";
    protected override Guid? UserId() => currentUser?.UserId;
}

