// Reference: backend/src/Smartlog.Api/Controllers/RolesController.cs
[ApiController]
[Route("api/roles")]
[Authorize]
public class RolesController(IDispatcher dispatcher) : ControllerBase {
    [HttpGet("{id:guid}")]
    public async Task<IActionResult> GetById([FromRoute] Guid id, CancellationToken ct)
        => Ok(ApiResult<RoleDto?>.Success(await dispatcher.QueryAsync(new GetRoleById.Query(id), ct)));

    [HttpPost]
    public async Task<IActionResult> Create([FromBody] CreateRole.Command command, CancellationToken ct)
        => Ok(ApiResult<Guid>.Success(await dispatcher.DispatchAsync(command, ct)));

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] UpdateRole.Command command, CancellationToken ct)
        => Ok(ApiResult.Success(await dispatcher.DispatchAsync(command with { Id = id }, ct)));

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
        => Ok(ApiResult.Success(await dispatcher.DispatchAsync(new DeleteRole.Command(id), ct)));

    [HttpPost("search")]
    public async Task<IActionResult> Search([FromBody] GetRolesList.Query query, CancellationToken ct)
        => Ok(ApiResult<DynamicGridResult>.Success(await dispatcher.QueryAsync(query, ct)));

    [HttpGet("lookup")]
    public async Task<IActionResult> Lookup([FromQuery] string? search, [FromQuery] bool? isActive = true, CancellationToken ct = default)
        => Ok(ApiResult<List<LookupDto>>.Success(await dispatcher.QueryAsync(new GetRolesLookup.Query { Search = search, IsActive = isActive }, ct)));
}

