// Reference: frontend/src/features/roles/api/roles.ts
export const rolesApi = {
    getRoles: async (params: SearchParams) => {
        const response = await apiClient.post('/roles/search', { ...params, formConfigCode: params.formConfigCode || 'SYSROLEG01' })
        return response.data.data
    },
    getRole: async (id: string) => {
        const response = await apiClient.get(`/roles/${id}`)
        return response.data.data
    },
    createRole: async (data: CreateCommand) => {
        const response = await apiClient.post('/roles', data)
        return response.data.data
    },
    updateRole: async (id: string, data: UpdateCommand) => {
        const response = await apiClient.put(`/roles/${id}`, data)
        return response.data.data
    },
    deleteRole: async (id: string) => {
        await apiClient.delete(`/roles/${id}`)
    },
}

